import React from "react";

class FAQ extends React.Component {
  render() {
    const {
      openFaq,
      handleFaq,
    } = this.props;

    /*
     * این اطلاعات فعلاً ثابت هستند.
     *
     * برای اتصال واقعی باید API مربوط به FAQ
     * برای Service اضافه شود.
     */

    const faqs = [
      {
        question: "این خدمت چقدر طول می‌کشد؟",
        answer:
          "مدت زمان انجام خدمت بر اساس اطلاعات سرویس مشخص می‌شود.",
      },
      {
        question: "آیا این خدمت درد دارد؟",
        answer:
          "برای پاسخ دقیق، اطلاعات مربوط به این موضوع باید از API دریافت شود.",
      },
      {
        question: "هر چند وقت یک‌بار باید انجامش بدهم؟",
        answer:
          "تعداد جلسات و فاصله جلسات باید از API مربوط به خدمت دریافت شود.",
      },
    ];

    return (
      <>
        <div className="detail-divider"></div>

        <h3 className="detail-h2">
          سوالات متداول
        </h3>

        <div className="faq-list">

          {faqs.map((faq, index) => (
            <div
              className={`faq-item ${
                openFaq === index
                  ? "open"
                  : ""
              }`}
              key={index}
            >

              <button
                className="faq-q"
                onClick={() =>
                  handleFaq(index)
                }
              >

                {faq.question}

                <svg
                  width="16"
                  height="16"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="m6 9 6 6 6-6" />
                </svg>

              </button>

              {openFaq === index && (
                <div className="faq-a">
                  <div className="faq-a-in">
                    {faq.answer}
                  </div>
                </div>
              )}

            </div>
          ))}

        </div>
      </>
    );
  }
}

export default FAQ;
